        d1a_player_pool <= 0xBFFFFFF3u &&
        d1a_player_stride == 0x14B00u && d1a_player_count == 0u &&
        d1a_mapping_base >= 0x40000000u &&
        d1a_mapping_base <= 0xBFFFFF24u &&
        d1a_local_mapping == 0xFFFFFFFFu;
