    // result is one when r11 is nonzero and zero otherwise.
    const uint32_t d1a_manager = static_cast<uint32_t>(d1a_context->r[26]);
    const uint32_t d1a_field1110_before = D1AlphaSafeReadU32BE(
        d1a_context, d1a_manager + 0x1110u, 0xFFFFFFFFu);
    const uint32_t d1a_field12a0 = D1AlphaSafeReadU32BE(
        d1a_context, d1a_manager + 0x12A0u, 0xFFFFFFFFu);
    const uint32_t d1a_slice_count = D1AlphaSafeReadU32BE(
        d1a_context, d1a_manager + 0x1008u, 0xFFFFFFFFu);
    const uint32_t d1a_state_manager =
        D1AlphaSafeReadU32BE(d1a_context, 0x83CF7E3Cu, 0u);
    const uint32_t d1a_controller_state = D1AlphaSafeReadU32BE(
        d1a_context, d1a_state_manager + 0xFCu, 0xFFFFFFFFu);
    const uint32_t d1a_target_manager =
        D1AlphaSafeReadU32BE(d1a_context, 0x83A0A118u, 0u);
