    const bool d1a_exact_missing_orbit_child =
        d1a_retain_private_bubble.load(std::memory_order_acquire) &&
        d1a_controller_state == 18u &&
        d1a_manager ==
            D1AlphaSafeReadU32BE(d1a_context, 0x83A0A118u, 0u) &&
        d1a_second_aux >= 0x40000000u &&
        d1a_second_aux <= 0xBFFFFABBu && d1a_selected_orbit_index &&
        d1a_relation == d1a_expected_relation &&
        D1AlphaSafeReadU32BE(d1a_context, d1a_relation + 0x14u, 0u) ==
            d1a_expected_relation_hash &&
        D1AlphaSafeReadU32BE(d1a_context, d1a_relation + 0x18u,
                             0xFFFFFFFFu) == 0u &&
        d1a_table_name_is_orbit &&
        d1a_child >= 0x40000000u && d1a_child <= 0xBFFFFFFBu &&
        D1AlphaSafeReadU32BE(d1a_context, d1a_child + 4u,
                             0xFFFFFFFFu) == 0u;
