    XELOGI(
        "D1A_TIGER_SELECTION_COUNT_RECONCILE controller={} manager={:08X} map={:08X} native={} live={} exact={} reconciled={}",
        d1a_controller_state, d1a_manager, d1a_selection_map,
        d1a_native_count, d1a_live_count, d1a_exact_map, d1a_reconciled);
