            static_cast<uint32_t>(d1a_record_address);
        d1a_record_base = *d1a_context->TranslateVirtualBE<uint32_t>(
            d1a_record + 0x10u);
        d1a_record_stride = *d1a_context->TranslateVirtualBE<uint32_t>(
            d1a_record + 0x30u);
        d1a_record_mask = *d1a_context->TranslateVirtualBE<uint32_t>(
            d1a_record + 0x34u);
        const bool d1a_entries_addressable =
            d1a_record_base >= 0x40000000u &&
            d1a_record_base <= 0xBFFFFFF7u &&
            d1a_record_stride != 0u && d1a_record_stride <= 0x10000u &&
            uint64_t{d1a_record_base} + uint64_t{d1a_record_stride} * 6u <=
                0xBFFFFFF7ull;
