          d1a_entry0_metadata =
              *d1a_context->TranslateVirtualBE<uint32_t>(d1a_record_base + 8u);
          d1a_entry6_metadata =
              *d1a_context->TranslateVirtualBE<uint32_t>(
                  d1a_record_base + d1a_record_stride * 6u + 8u);
