    uint32_t d1a_root_before = 0xFFFFFFFFu;
    uint32_t d1a_root_after = 0xFFFFFFFFu;
    uint32_t d1a_root_count_before = 0xFFFFFFFFu;
    uint32_t d1a_root_count_after = 0xFFFFFFFFu;
    bool d1a_root_restored = false;
    uint32_t d1a_slice_count_before = 0xFFFFFFFFu;
    uint32_t d1a_slice_count_after = 0xFFFFFFFFu;
    bool d1a_slice_count_restored = false;
    uint32_t d1a_state25_root_resolved = 0u;
    uint32_t d1a_aux_handle_before = 0xFFFFFFFFu;
    uint32_t d1a_aux_handle_after = 0xFFFFFFFFu;
    uint32_t d1a_aux_offset_before = 0xFFFFFFFFu;
    uint32_t d1a_aux_offset_after = 0xFFFFFFFFu;
