        *d1a_context->TranslateVirtualBE<uint32_t>(0x83CF7E4Cu);
    uint32_t d1a_client_selection_before = 0xFFFFFFFFu;
    uint32_t d1a_client_selection_after = 0xFFFFFFFFu;
