    if (d1a_exact && d1a_pvp_active_contract &&
        d1a_after == 0x545AEC79u && d1a_root_after == 0x80BDA006u &&
        d1a_activity_client >= 0x40000000u &&
        d1a_activity_client <= 0xBFFFFE73u) {
      auto* d1a_client_selection =
          d1a_context->TranslateVirtualBE<uint32_t>(d1a_activity_client +
                                                    0x184u);
      d1a_client_selection_before = *d1a_client_selection;
      d1a_client_selection_after = *d1a_client_selection;
    }
