    // publisher is about to write, strictly read-only.
    const uint32_t d1a_client = static_cast<uint32_t>(d1a_context->r[23]);
    uint32_t d1a_handle90 = 0xFFFFFFFFu;
    uint32_t d1a_region_e8 = 0xFFFFFFFFu;
    uint32_t d1a_region_ec = 0xFFFFFFFFu;
    uint32_t d1a_status = 0xFFFFFFFFu;
    uint32_t d1a_active = 0xFFFFFFFFu;
