          *d1a_context->TranslateVirtualBE<uint32_t>(d1a_client + 0xE8u);
      d1a_region_ec =
          *d1a_context->TranslateVirtualBE<uint32_t>(d1a_client + 0xECu);
      d1a_status =
          *d1a_context->TranslateVirtualBE<uint32_t>(d1a_client + 0x84u);
