    static std::chrono::steady_clock::time_point
        d1a_rendered_world_player_bind_ready_at{};
    static bool d1a_rendered_world_player_bind_completed = false;
    static std::chrono::steady_clock::time_point
        d1a_rendered_world_respawn_ready_at{};
    static bool d1a_rendered_world_respawn_replayed = false;
    // Run 1108 reached the exact retained destination with a natively rebuilt
