    // linked EC700000 to our heap-backed accessor. The heap objects survive;
    // only rearm the resolver scan and callback when that exact link is gone.
    const bool d1a_second_cycle_native_player_ready =
        d1a_retained_destination_in_world &&
        d1a_native_player_pool >= 0x40000000u &&
        d1a_native_player_pool <= 0xBFFFFFF3u &&
        d1a_native_player_count == 1u &&
        d1a_native_player_handle == 0xEC700000u &&
        d1a_native_local_mapping == d1a_native_player_handle;
    const bool d1a_second_cycle_player_owner_rearm_ready =
        d1a_first_state30_seen &&
        (d1a_second_cycle_native_player_ready ||
         d1a_destination_ready_for_player_owner);
    if (d1a_second_cycle_player_owner_rearm_ready &&
        d1a_forced_player_component_scan_completed &&
        d1a_forced_player_component_accessor == 0xEC700000u &&
        d1a_forced_player_entity_object >= 0x30000000u &&
        d1a_forced_player_entity_object <= 0xBFFFFFFFu) {
      const uint32_t d1a_entity_pool_base =
          D1AlphaSafeReadU32BE(d1a_context, 0x83A05918u, 0u);
      const uint32_t d1a_entity_pool_stride =
          D1AlphaSafeReadU32BE(d1a_context, 0x83A0591Cu, 0u);
      const uint32_t d1a_entity_pool_mask =
          D1AlphaSafeReadU32BE(d1a_context, 0x83A05934u, 0u);
      const uint32_t d1a_entity_record = d1a_entity_pool_base;
      const uint32_t d1a_record_flags = D1AlphaSafeReadU32BE(
          d1a_context, d1a_entity_record + 0x8u, 0xFFFFFFFFu);
      const uint32_t d1a_adjustment =
          d1a_record_flags & d1a_entity_pool_mask;
      const uint32_t d1a_resolved_entity =
          d1a_entity_record >= d1a_adjustment
              ? d1a_entity_record - d1a_adjustment
              : 0u;
      const bool d1a_accessor_link_exact =
          d1a_entity_pool_base >= 0x40000000u &&
          d1a_entity_pool_base <= 0xBFFFFFE7u &&
          d1a_entity_pool_stride == 0x18u &&
          d1a_entity_pool_mask == 0xFFFFFFFFu &&
          d1a_resolved_entity == d1a_forced_player_entity_object;
      if (!d1a_accessor_link_exact) {
        d1a_forced_player_component_scan_completed = false;
        d1a_forced_player_owner_callback_completed = false;
        d1a_forced_player_component_accessor = 0u;
        d1a_forced_player_component_handle = 0u;
        XELOGW(
            "D1A_SECOND_CYCLE_PLAYER_OWNER_REARM record={:08X} flags={:08X} resolved={:08X} expected={:08X} player={:08X} exact=true",
            d1a_entity_record, d1a_record_flags, d1a_resolved_entity,
            d1a_forced_player_entity_object, d1a_native_player_handle);
      }
    }
    // Run 978 proved the raw owner experiment is not a valid Tiger object
    // creation path. +0x14 is an entity/component accessor, while +0x1C is
