              D1AlphaSafeReadU32BE(d1a_context, d1a_marker_address,
                                   0xFFFFFFFFu) ==
                  d1a_retained_owner_entity_pool_marker &&
              D1AlphaSafeReadU32BE(d1a_context,
                                   d1a_donor_address + 0x64u,
                                   0xFFFFFFFFu) ==
                  d1a_retained_owner_component_associated &&
              std::memcmp(
                  d1a_context->TranslateVirtual<const uint8_t*>(
                      d1a_donor_address + 0xA0u),
                  d1a_retained_owner_component_transform,
                  sizeof(d1a_retained_owner_component_transform)) == 0;
