    static thread_local uint32_t d1a_periodic_last[7][4] = {};
    uint32_t d1a_stage_index = 0u;
    if (d1a_function == 0x8291CF04u) d1a_stage_index = 1u;
    if (d1a_function == 0x8291CF2Cu) d1a_stage_index = 2u;
    if (d1a_function == 0x8291CF3Cu) d1a_stage_index = 3u;
    if (d1a_function == 0x8291CF50u) d1a_stage_index = 4u;
    if (d1a_function == 0x8291CF64u) d1a_stage_index = 5u;
    if (d1a_function == 0x8291CF78u) d1a_stage_index = 6u;
