      d1a_periodic_last[d1a_stage_index][d1a_slot] = d1a_gate;
      XELOGI(
          "D1A_PERIODIC_ACTIVITY stage={} slot={} value={:08X} manager={:08X} record={:08X} object={:08X}",
          d1a_stage, d1a_slot, d1a_gate,
          static_cast<uint32_t>(d1a_context->r[23]),
          static_cast<uint32_t>(d1a_context->r[27]),
          static_cast<uint32_t>(d1a_context->r[29]));
