    const uint32_t d1a_permitted =
        static_cast<uint32_t>(d1a_context->r[3]) & 0xFFu;
    d1a_context->r[11] = d1a_permitted;
    const uint32_t d1a_activity =
        static_cast<uint32_t>(d1a_context->r[21]) & 0xFFFFu;
    const int32_t d1a_member_index =
        static_cast<int32_t>(static_cast<uint32_t>(d1a_context->r[31]));
    const uint32_t d1a_output =
        static_cast<uint32_t>(d1a_context->r[27]);
