        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_output);
    const uint32_t d1a_mask =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_output + 4u);
    static thread_local uint64_t d1a_last_member_permission =
        0xFFFFFFFFFFFFFFFFull;
