        (static_cast<uint64_t>(d1a_activity) << 48u) |
        (static_cast<uint64_t>(static_cast<uint32_t>(d1a_member_index) &
                               0xFFFFu)
         << 32u) |
        (static_cast<uint64_t>(d1a_permitted) << 31u) | d1a_mask;
