    // ownership manager and its asynchronous lifecycle untouched.
    const uint32_t d1a_catalog = 0x84031164u;
    const uint32_t d1a_catalog_state =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_catalog + 0x1Cu);
