        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_manager + 0x104u);
    const uint32_t d1a_count =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_manager + 0x100u);
    const uint32_t d1a_ready =
        *d1a_context->TranslateVirtual<const uint8_t*>(d1a_manager + 0x10Cu);
    const uint32_t d1a_initialized =
        *d1a_context->TranslateVirtual<const uint8_t*>(d1a_manager + 0x10Du);
