    const uint32_t d1a_phase =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_manager);
    const uint32_t d1a_subject =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_manager + 8u);
    const uint32_t d1a_callback =
        *d1a_context->TranslateVirtualBE<uint32_t>(d1a_manager + 0xCu);
