          d1a_update = *d1a_context->TranslateVirtualBE<uint32_t>(
              d1a_vtable + 0x14u);
          d1a_finalize = *d1a_context->TranslateVirtualBE<uint32_t>(
              d1a_vtable + 0x18u);
