          d1a_pending = *d1a_context->TranslateVirtualBE<uint64_t>(
              d1a_object + 0x3F0u);
          d1a_completed = *d1a_context->TranslateVirtualBE<uint64_t>(
              d1a_object + 0x400u);
          d1a_flags = *d1a_context->TranslateVirtual<const uint8_t*>(
              d1a_object + 0x408u);
          d1a_initialized =
              *d1a_context->TranslateVirtual<const uint8_t*>(
                  d1a_object + 0x409u);
          d1a_event = *d1a_context->TranslateVirtualBE<uint32_t>(
              d1a_object + 0x40Cu);
          d1a_transition_type =
              *d1a_context->TranslateVirtualBE<uint32_t>(
                  d1a_object + 0x410u);
          d1a_transition_reason =
              *d1a_context->TranslateVirtualBE<uint32_t>(
                  d1a_object + 0x414u);
