      if (d1a_precache_slot0_restored) {
        XELOGI(
            "D1A_STATE26_PRECACHE_SOURCE_RESTORED manager={:08X} mode={} slot0={:08X}->{:08X} source={:08X}",
            d1a_precache_manager, d1a_precache_mode,
            d1a_precache_slot0_before, d1a_precache_slot0_after,
            d1a_precache_authoritative_base);
      }
      static thread_local bool d1a_state26_mapping_reported = false;
