      const uint32_t d1a_global_state_manager =
          *d1a_context->TranslateVirtualBE<uint32_t>(0x83CF7E3Cu);
      const uint32_t d1a_precache_manager =
          *d1a_context->TranslateVirtualBE<uint32_t>(0x83CF7E48u);
      const uint32_t d1a_selection_config =
          *d1a_context->TranslateVirtualBE<uint32_t>(0x83FF3984u);
      const uint32_t d1a_tiger_manager =
          *d1a_context->TranslateVirtualBE<uint32_t>(0x83A0A118u);
