            d1a_precache_slots[0] == 0xFFFFFFFFu &&
            d1a_precache_slots[1] == 0x00FCC000u &&
            d1a_precache_slots[2] == 0xFFFFFFFFu &&
            d1a_precache_slots[3] == 2u;
