      // live packed pool and restore it only when the one-entry table still
      // identifies the selected Greenhouse activity.
      constexpr uint32_t kD1AlphaInvestmentHandle = 0x80B86004u;
      const uint32_t d1a_activity_manager =
          *d1a_context->TranslateVirtualBE<uint32_t>(0x83CF7E44u);
