      uint32_t d1a_investment_count = 0xFFFFFFFFu;
      uint32_t d1a_investment_delta = 0xFFFFFFFFu;
      uint32_t d1a_investment_word34 = 0xFFFFFFFFu;
      uint32_t d1a_investment_key = 0xFFFFFFFFu;
      uint32_t d1a_table518_before = 0xFFFFFFFFu;
      uint32_t d1a_table518_after = 0xFFFFFFFFu;
      bool d1a_table518_restored = false;
      bool d1a_investment_registry_captured = false;
