        d1a_second_cycle_orbit_tiger_name_delta > 0u &&
        d1a_second_cycle_orbit_tiger_name_delta < 0x7F8u &&
        std::memcmp(d1a_context->TranslateVirtual<const char*>(
                        d1a_second_cycle_orbit_tiger_name),
                    kD1AlphaRetainedOrbitTigerName,
                    sizeof(kD1AlphaRetainedOrbitTigerName)) == 0;
    const bool d1a_second_cycle_orbit_tiger_root_route =
        d1a_handle == 0x80ADE012u &&
        // Run 640 proved that the state-18 physics attachment-cluster iterator
        // resolves this same handle at 0x836566A8 and immediately passes the
        // result to 0x83653BB8, whose +0xC/+0x10 table contract is satisfied by
        // this already-validated immutable snapshot.
        (d1a_packed_trace_caller == 0x835F8BA8u ||
         d1a_packed_trace_caller == 0x835F95B8u ||
         d1a_packed_trace_caller == 0x835F9310u ||
         d1a_packed_trace_caller == 0x835FE730u ||
         d1a_packed_trace_caller == 0x836566A8u) &&
        d1a_physics_controller == 18u &&
        d1a_retain_private_bubble.load(std::memory_order_acquire) &&
        d1a_second_cycle_orbit_tiger_snapshot_exact;
    if (d1a_second_cycle_orbit_tiger_root_route) {
      d1a_fallback_result = d1a_second_cycle_orbit_tiger_snapshot_value;
    }
    const uint32_t d1a_second_cycle_orbit_handle_snapshot_value =
        d1a_second_cycle_orbit_handle_snapshot.load(
            std::memory_order_acquire);
    const uint32_t d1a_second_cycle_orbit_handle_index =
        (d1a_handle & 0xFFFFFFC0u) == 0x80ADE000u
            ? d1a_handle & 0x3Fu
            : 0xFFFFFFFFu;
    const uint32_t d1a_second_cycle_orbit_handle_mask =
        d1a_second_cycle_orbit_handle_index < 32u
            ? d1a_second_cycle_orbit_handle_mask_low.load(
                  std::memory_order_acquire)
            : d1a_second_cycle_orbit_handle_mask_high.load(
                  std::memory_order_acquire);
    const bool d1a_second_cycle_orbit_handle_present =
        d1a_second_cycle_orbit_handle_index < 64u &&
        (d1a_second_cycle_orbit_handle_mask &
         (1u << (d1a_second_cycle_orbit_handle_index & 31u))) != 0u;
    bool d1a_second_cycle_orbit_handle_slice_exact =
        d1a_second_cycle_orbit_handle_snapshot_value >= 0x30000000u &&
        d1a_second_cycle_orbit_handle_snapshot_value <= 0x3FFFBFFFu &&
        (d1a_second_cycle_orbit_handle_mask_low.load(
             std::memory_order_acquire) &
         0x00007F80u) == 0x00007F80u;
    for (uint32_t d1a_orbit_index = 7u;
         d1a_second_cycle_orbit_handle_slice_exact &&
         d1a_orbit_index <= 14u;
         ++d1a_orbit_index) {
      const uint32_t d1a_orbit_record =
          d1a_second_cycle_orbit_handle_snapshot_value +
          d1a_orbit_index * 0x100u;
      d1a_second_cycle_orbit_handle_slice_exact =
          D1AlphaSafeReadU32BE(d1a_context, d1a_orbit_record, 0u) == 0x22u &&
          D1AlphaSafeReadU32BE(d1a_context, d1a_orbit_record + 0xCu,
                               0xFFFFFFFFu) ==
              d1a_orbit_index - 7u &&
          D1AlphaSafeReadU32BE(d1a_context, d1a_orbit_record + 0x10u, 0u) ==
              0x80ADE010u &&
          D1AlphaSafeReadU32BE(d1a_context, d1a_orbit_record + 0x1Cu, 0u) ==
              0x6F726269u &&
          D1AlphaSafeReadU16BE(d1a_context, d1a_orbit_record + 0x20u,
                               0xFFFFu) == 0x7400u;
    }
    const bool d1a_second_cycle_orbit_handle_route =
        d1a_second_cycle_orbit_handle_present &&
        // The root and registry have larger, separately validated contracts.
        d1a_handle != 0x80ADE004u && d1a_handle != 0x80ADE012u &&
        d1a_packed_trace_caller >= 0x835F8000u &&
        d1a_packed_trace_caller < 0x83600000u &&
        // States 20..25 are one continuous pre-load setup ladder. They query
        // the same native Orbit relation records after cleanup and before
        // state 26 begins loading the destination's own initial slices. Keep
        // this oracle awake for that complete interval, but answer only exact
        // handles in the fully validated immutable eight-record Orbit slice.
        d1a_physics_controller >= 17u && d1a_physics_controller <= 25u &&
        d1a_retain_private_bubble.load(std::memory_order_acquire) &&
        d1a_second_cycle_orbit_handle_slice_exact;
    // 0x835F89B0 is a pure relation validator. Once the immutable native
    // slice proves all eight indexed records are the same Orbit relation, its
    // answer is known. Let the current packed resolver unwind normally, but
    // return directly through the validator's own epilogue instead of waking
    // every retired dependency beneath it.
    const bool d1a_second_cycle_orbit_validator_oracle =
        d1a_second_cycle_orbit_tiger_root_route &&
        d1a_packed_trace_caller == 0x835F8BA8u &&
        d1a_second_cycle_orbit_handle_slice_exact;
    if (d1a_second_cycle_orbit_validator_oracle) {
      d1a_context->r[17] = 1u;
      d1a_context->lr = 0x835F9160u;
    }
