    const bool d1a_retained_destination_aux_child_route =
        d1a_first_state30_seen &&
        d1a_retain_private_bubble.load(std::memory_order_acquire) &&
        d1a_physics_controller == 26u && d1a_live_aux_record_exact &&
        d1a_aux_child_offset == 0x0B4u && d1a_aux_child_record_exact;
