      break;
    case 0xD56C:
      CallNative(TrapDebugBreak, 0x8288956Cu);
      break;
    case 0xD830:
      CallNative(TrapDebugBreak, 0x835F8C30u);
      break;
    case 0xDF48:
      CallNative(TrapDebugBreak, 0x8363DF48u);
      break;
    case 0xD080:
      CallNative(TrapDebugBreak, 0x83665080u);
