    case 0xD100:
      // The two unsolicited receive probes live inside one guest function.
      // Their dedicated HIR trap codes preserve the exact patch site without
      // changing the handler key used by any established compatibility trap.
      CallNative(TrapDebugBreak, 0x830E7600u);
